    const groups=['01 · Foundations','02 · Core Usage','03 · Advanced & Integration','04 · Production'].map((g,i)=>({group:g,description:i===0?'Why it exists and the mental model.':i===1?'Daily usage, commands and configuration.':i===2?'Integrations, scaling and advanced behavior.':'Security, troubleshooting and production operation.',topics:topics.slice(i*chunk,(i+1)*chunk)})).filter(g=>g.topics.length);
    const arch=c.architecture||['User / Source','Configuration',' '+c.name+' ','Connected System','Production Outcome'];
    const connects=c.connectsTo||[];
    const prereq=c.prerequisites||['Linux basics'];
    const after=c.after||c.nextTools||connects.slice(0,3);
    const commands=c.commands?.length?c.commands:[['--help','Discover supported syntax and options.'],['version','Verify the installed version before debugging behavior.']];
